function normalizeFavoriteColor(value) {
  const id = String(value || "").toLocaleLowerCase();
  return FAVORITE_COLORS.some((color) => color.id === id) ? id : "yellow";
}

function favoriteColorValue(value) {
  const id = normalizeFavoriteColor(value);
  return FAVORITE_COLORS.find((color) => color.id === id)?.value || FAVORITE_COLORS[0].value;
}

function normalizePaperTag(value) {
  let tag = stripMarkup(value || "").normalize("NFKC").trim().replace(/^#+/, "");
  if (!tag) return "";
  tag = tag
    .replace(/[\s\u00a0]+/g, "-")
    .replace(/[^\p{L}\p{N}_/-]+/gu, "-")
    .replace(/-{2,}/g, "-")
    .replace(/\/{2,}/g, "/")
    .replace(/^[-/]+|[-/]+$/g, "");
  if (!tag || /^\d+(?:[-/]\d+)*$/.test(tag)) return "";
  return tag.slice(0, 100).replace(/[-/]+$/g, "");
}

function normalizePaperTags(values = []) {
  const source = Array.isArray(values) ? values : String(values || "").split(/[;,]/);
  const result = [];
  const seen = new Set();
  source.forEach((value) => {
    const tag = normalizePaperTag(value);
    const key = tag.toLocaleLowerCase();
    if (!tag || seen.has(key)) return;
    seen.add(key);
    result.push(tag);
  });
  return result;
}
